-- Pairs who repeatedly serve together, seeded as a PREFERENCE not a rule: the
-- evidence says they choose each other, not that they must be forced together.
-- A person may appear in several pairs (Pete serves with both Ruth and Heather),
-- which is why this is a table and not a spouse column on people.
INSERT OR IGNORE INTO pairings (person_a_id,person_b_id,role_id,mode,strength,note)
SELECT MIN(pa.id,pb.id), MAX(pa.id,pb.id), NULL, 'together', 'prefer', 'Served together 8 times in the Sept-Nov rota' FROM people pa, people pb WHERE pa.display_name='Sheila' AND pb.display_name='Sue';
INSERT OR IGNORE INTO pairings (person_a_id,person_b_id,role_id,mode,strength,note)
SELECT MIN(pa.id,pb.id), MAX(pa.id,pb.id), NULL, 'together', 'prefer', 'Served together 8 times in the Sept-Nov rota' FROM people pa, people pb WHERE pa.display_name='Pete' AND pb.display_name='Ruth';
